function paintIcons(root = document) {
  root.querySelectorAll('i[data-i]').forEach(e => { const p = LINE_ICONS[e.dataset.i]; if (!p) return; e.outerHTML = `<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`; });
  root.querySelectorAll('i[data-g]').forEach(e => { const g = GAME_ICONS[e.dataset.g]; if (!g) return; e.outerHTML = `<svg class="ic gic" viewBox="${g[0]}" fill="currentColor" aria-hidden="true">${g[1]}</svg>`; });
}
